import{R as e,e as n,f as o,U as i}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"iContact","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/icontact.md","filePath":"integrations/email-marketing/icontact.md","lastUpdated":1775908585000}'),a={name:"integrations/email-marketing/icontact.md"};function r(s,t,l,c,g,h){return n(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="icontact" tabindex="-1">iContact <a class="header-anchor" href="#icontact" aria-label="Permalink to &quot;iContact&quot;">​</a></h1><p>Follow the below steps to connect to the iContact API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select iContact as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-icontact-api" tabindex="-1">Step 2. Connect to the iContact API <a class="header-anchor" href="#step-2-connect-to-the-icontact-api" aria-label="Permalink to &quot;Step 2. Connect to the iContact API&quot;">​</a></h3><ol><li>Go to <a href="https://www.icontact.com/" target="_blank">iContact</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Settings &amp; Billing</strong>.</li><li>Click on <strong>iContact Integrations</strong>.</li><li>Find the <strong>Custom API Integrations</strong> item and click the <strong>Create</strong> button.</li><li>Copy the <strong>Application ID (AppId)</strong> from iContact and paste in the <strong>Application ID</strong> field in Formie.</li><li>Copy the <strong>Username / Email Address</strong> from iContact and paste in the <strong>Username</strong> field in Formie.</li><li>Copy the <strong>Password</strong> from iContact and paste in the <strong>Password</strong> field in Formie.</li><li>Copy the <strong>Account ID</strong> from iContact and paste in the <strong>Account ID</strong> field in Formie.</li><li>Copy the <strong>Client Folder ID</strong> from iContact and paste in the <strong>Client Folder ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(a,[["render",r]]);export{p as __pageData,m as default};
